// Extend the same app-first shell to existing guarded utility documents only.
// Retain the current core entry, every original module, asset, binding and flag.
import assert from'node:assert/strict';import{readFileSync,writeFileSync,existsSync}from'node:fs';import{createHash}from'node:crypto';
const phase=process.argv[2],file='first-paint-utility-publication-state.json',name='shift-core',account='9e5386dcf455be34c582d93f8bfc79e6',zone='66ec3268950adcfc837b7b8b2f8356ed',ep='/accounts/'+account+'/workers/scripts/'+name,prefix='first-paint-utilities-20261101/';
const auth=readFileSync('/Users/shiftsometimberltd/Library/Preferences/.wrangler/config/default.toml','utf8'),token=process.env.CLOUDFLARE_API_TOKEN||auth.match(/^oauth_token\s*=\s*"([^"\n]+)"/m)?.[1];assert(token);
const digest=b=>createHash('sha256').update(b).digest('hex'),hashes=ms=>Object.fromEntries(ms.map(m=>[m.name,digest(Buffer.from(m.content_base64,'base64'))]).sort(([a],[b])=>a.localeCompare(b))),sorted=bs=>[...bs].sort((a,b)=>a.name.localeCompare(b.name));
let state=existsSync(file)?JSON.parse(readFileSync(file)):{kind:'MY_TIMBER_UTILITY_FIRST_PAINT_RELEASE',createdAt:new Date().toISOString(),name};const save=()=>writeFileSync(file,JSON.stringify(state,null,2)+'\n');
async function cf(path,method='GET',body){const multi=body instanceof FormData,r=await fetch('https://api.cloudflare.com/client/v4'+path,{method,headers:{Authorization:'Bearer '+token,...(body&&!multi?{'Content-Type':'application/json'}:{})},body:multi?body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(55000)}),j=await r.json();assert(r.ok&&j.success,method+' '+path+': '+JSON.stringify(j.errors));return j.result;}
const active=async n=>[...(await cf('/accounts/'+account+'/workers/scripts/'+n+'/deployments')).deployments].sort((a,b)=>b.created_on.localeCompare(a.created_on))[0],version=id=>cf('/accounts/'+account+'/workers/workers/'+name+'/versions/'+id+'?include=modules'),routes=()=>cf('/zones/'+zone+'/workers/routes');
async function guard(){assert.equal((await active(name)).id,state.currentDeployment,'Core serving baseline advanced; reconcile and retain the newer work');for(const o of state.relatedOwners)assert.equal((await active(o.name)).id,o.currentDeployment,'Related member baseline advanced');assert.deepEqual(await routes(),state.routes,'Routes changed');assert.deepEqual(await cf(ep+'/schedules'),state.schedules,'Schedules changed');}
async function preserved(v){assert.deepEqual(sorted(v.bindings),sorted(state.bindings));assert.equal(v.compatibility_date,state.compatibilityDate);assert.deepEqual(v.compatibility_flags||[],state.compatibilityFlags);assert.deepEqual(v.assets??v.resources?.script_runtime?.assets,state.assets);let settings;for(const[k,x]of Object.entries(state.operatingConfiguration)){let value=v[k]??v.resources?.script_runtime?.[k];if(value===undefined){settings??=await cf(ep+'/settings');value=settings[k];}assert.deepEqual(value,x,k+' changed');}}
async function verifyNew(){const v=await version(state.versionId);assert.equal(v.main_module,prefix+'entry.mjs');await preserved(v);assert.deepEqual(hashes(v.modules),state.moduleHashes);return v;}
async function baseline(){if(state.baselineVerifiedAt){await guard();return;}const b=JSON.parse(readFileSync('first-paint-utility-serving-baseline.json')),a=await active(name);assert.equal(a.id,b.deployment.id,'Core advanced since inspection; refresh the captured baseline before preparing');assert.deepEqual(a.versions,b.deployment.versions);assert.equal(a.versions.length,1);assert(!b.version.modules.some(m=>m.name.startsWith(prefix)),'Do not duplicate an existing utility integration');const member=JSON.parse(readFileSync('first-paint-publication-state.json')),v=b.version,runtime=v.resources?.script_runtime||{};state={...state,previousVersion:a.versions[0].version_id,baselineDeployment:a.id,currentDeployment:a.id,oldMain:v.main_module,bindings:v.bindings,compatibilityDate:v.compatibility_date,compatibilityFlags:v.compatibility_flags||[],assets:v.assets??runtime.assets,operatingConfiguration:{},baselineModuleHashes:hashes(v.modules),schedules:b.schedules,routes:await routes(),relatedOwners:member.owners.map(o=>({name:o.name,currentDeployment:o.currentDeployment,versionId:o.versionId}))};for(const k of['usage_model','limits','placement','cache_options','observability','tail_consumers','logpush']){const x=v[k]??runtime[k]??b.settings[k];if(x!==undefined)state.operatingConfiguration[k]=x;}state.baselineVerifiedAt=new Date().toISOString();save();await guard();console.log('UTILITY_BASELINE_VERIFIED',state.previousVersion,state.oldMain,Object.keys(state.baselineModuleHashes).length,state.bindings.length);}
async function stage(){assert(state.baselineVerifiedAt);await guard();if(state.versionId){await verifyNew();return;}assert(!state.uploadIntent,'Inspect unknown upload outcome before any retry');const source=JSON.parse(readFileSync('first-paint-utility-source.json'));assert.match(source.commit,/^[a-f0-9]{40}$/);const b=JSON.parse(readFileSync('first-paint-utility-serving-baseline.json')),v=b.version;assert.equal(b.deployment.id,state.baselineDeployment);assert.deepEqual(hashes(v.modules),state.baselineModuleHashes);await preserved(v);const bytes=readFileSync('bundle-first-paint-utilities.mjs');assert.equal(digest(bytes),source.bundleSHA256);const entry='import original from "../'+state.oldMain+'";\nexport * from "../'+state.oldMain+'";\nimport {wrapMemberFirstPaintUtilities} from "./documents.mjs";\nexport default wrapMemberFirstPaintUtilities(original);\n',modules=[...v.modules,{name:prefix+'documents.mjs',content_type:'application/javascript+module',content_base64:bytes.toString('base64')},{name:prefix+'entry.mjs',content_type:'application/javascript+module',content_base64:Buffer.from(entry).toString('base64')}];state.source=source.commit;state.bundleSHA256=digest(bytes);state.moduleHashes=hashes(modules);assert.equal(modules.length,Object.keys(state.baselineModuleHashes).length+2);for(const[k,h]of Object.entries(state.baselineModuleHashes))assert.equal(state.moduleHashes[k],h);const metadata={main_module:prefix+'entry.mjs',compatibility_date:state.compatibilityDate,compatibility_flags:state.compatibilityFlags,bindings:state.bindings.map(b=>({type:'inherit',name:b.name})),keep_assets:true,...state.operatingConfiguration,annotations:{'workers/message':'Approved guarded member utility first paint '+state.source,'workers/tag':'member-first-paint-'+state.source.slice(0,12)}},form=new FormData();form.set('metadata',new Blob([JSON.stringify(metadata)],{type:'application/json'}),'metadata.json');for(const m of modules)form.set(m.name,new Blob([Buffer.from(m.content_base64,'base64')],{type:m.content_type||'application/javascript+module'}),m.name);state.uploadIntent={at:new Date().toISOString(),source:state.source,baseline:state.currentDeployment};save();await guard();const uploaded=await cf(ep+'/versions?bindings_inheritance=strict','POST',form);state.versionId=uploaded.id;save();await verifyNew();await guard();state.stagedVerifiedAt=new Date().toISOString();save();console.log('UTILITY_SCOPED_UPLOAD_VERIFIED',state.versionId,'original modules unchanged',Object.keys(state.baselineModuleHashes).length);}
async function deploy(mode){assert(state.stagedVerifiedAt);await verifyNew();const desired=mode==='zero'?[{version_id:state.previousVersion,percentage:100},{version_id:state.versionId,percentage:0}]:[{version_id:state.versionId,percentage:100}],message='My Timber utility first paint '+state.source+' '+mode,before=await active(name);if(before.annotations?.['workers/message']===message&&JSON.stringify(before.versions)===JSON.stringify(desired)){state.currentDeployment=before.id;state[mode+'VerifiedAt']=new Date().toISOString();save();await guard();return;}await guard();if(mode==='live')assert(state.candidateAcceptedAt);assert(!state.deploymentIntent||state.deploymentIntent.finished,'Unknown deployment outcome; inspect provider');state.deploymentIntent={mode,message,at:new Date().toISOString(),finished:false};save();const pub=await cf(ep+'/deployments','POST',{strategy:'percentage',versions:desired,annotations:{'workers/message':message}});state.currentDeployment=pub.id;save();const observed=await active(name);assert.equal(observed.id,pub.id);assert.deepEqual(observed.versions,desired);state[mode+'VerifiedAt']=new Date().toISOString();state.deploymentIntent.finished=true;save();await guard();console.log('UTILITY_PUBLICATION_VERIFIED',mode,state.versionId,pub.id);}
async function accept(){await guard();assert(state.zeroVerifiedAt);state.acceptance=[];for(const engine of['chromium','webkit']){const path='first-paint-utility-candidate-'+engine+'.json',b=readFileSync(path),r=JSON.parse(b);assert(r.verified);assert.equal(r.source,state.source);assert.equal(r.firstPaintChecks.length,11);assert(r.firstPaintChecks.every(c=>c.websiteFrames===0&&c.privateContentGuarded&&c.anonymousSignInPreserved));state.acceptance.push({path,sha256:digest(b)});}state.candidateAcceptedAt=new Date().toISOString();save();console.log('UTILITY_CANDIDATE_ACCEPTED');}
try{if(phase==='baseline')await baseline();else if(phase==='stage')await stage();else if(phase==='zero'||phase==='live')await deploy(phase);else if(phase==='accept')await accept();else if(phase==='status'){const a=await active(name);console.log('UTILITY_CURRENT_PROVIDER_STATE',JSON.stringify({name,id:a.id,versions:a.versions,message:a.annotations?.['workers/message']}));}else throw Error('Use baseline, stage, zero, accept, live or status');state.updatedAt=new Date().toISOString();state.lastSuccessfulPhase=phase;delete state.failure;save();}catch(e){state.failure={phase,message:e.message,at:new Date().toISOString()};save();console.error('UTILITY_FIRST_PAINT_STOPPED',e.message);process.exitCode=1;}
